    "explanation": "1. CONCEPT:\nModern redefinition of SI base units via fundamental physical constants.\n\n2. GIVEN:\nRedefinition of the kilogram (effective May 20, 2019).\n\n3. FORMULA / PRINCIPLE:\nE = h ν = m c²  =>  h has units kg·m²·s⁻¹. Fixing h and c, s defines the kilogram.\n\n4. STEP-BY-STEP SOLUTION:\n1. Prior to 2019, the kilogram was defined by a physical platinum-iridium cylinder stored in France.\n2. On World Metrology Day 2019, the kilogram was redefined by fixing Planck's constant h to exactly 6.62607015 × 10⁻³⁴ J·s (kg·m²·s⁻¹).\n3. By combining fixed h with fixed c (meter) and fixed Δν_Cs (second), the kilogram is realized using a Kibble balance.\n\n5. FINAL ANSWER:\nOption B: Planck's constant h\n\n6. QUICK TIP:\nNEET Modern Physics Connection: Kilogram -> Planck constant h; Meter -> Speed of light c; Second -> Cesium transition frequency; Ampere -> Elementary charge e.",
