    "question": "A system of units adopts the velocity of light c = 3 × 10⁸ m/s, gravitational constant G = 6.67 × 10⁻¹¹ N·m²/kg², and Planck's constant h = 6.63 × 10⁻³⁴ J·s as the fundamental units. The unit of length in this system is proportional to:",
    "options": {
      "A": "√(h G / c³)",
      "B": "√(h c / G)",
      "C": "√(G c / h³)",
      "D": "√(h G c³)"
    },
