    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nDerivation of the Planck length from fundamental constants.\n\n2. GIVEN:\nConstants c, G, h as fundamental units. Find Length L.\n\n3. FORMULA / PRINCIPLE:\nL = c^x G^y h^z. [L] = [L T⁻¹]^x [M⁻¹ L³ T⁻²]^y [M L² T⁻¹]^z.\n\n4. STEP-BY-STEP SOLUTION:\n1. Equate mass powers: -y + z = 0  =>  y = z.\n2. Equate length powers: x + 3y + 2z = 1  =>  x + 5y = 1.\n3. Equate time powers: -x - 2y - z = 0  =>  x + 3y = 0  =>  x = -3y.\n4. Substitute into length equation: -3y + 5y = 1  =>  2y = 1  =>  y = 1/2.\n5. Therefore, z = 1/2, and x = -3(1/2) = -3/2.\n6. L ∝ c^(-3/2) G^(1/2) h^(1/2) = √(h G / c³).\n\n5. FINAL ANSWER:\nOption A: √(h G / c³)\n\n6. QUICK TIP:\nNEET Gold Formula: Planck length l_p = √(h G / c³) ≈ 1.6 × 10⁻³⁵ m. Essential formula in high-energy physics!",
