    "correctAnswer": "B",
    "correctIndex": 1,
    "explanation": "1. CONCEPT:\nRelation between magnetic flux and induced electromotive force.\n\n2. GIVEN:\nQuantity: Magnetic flux Φ.\n\n3. FORMULA / PRINCIPLE:\nFaraday's law of electromagnetic induction: e = -dΦ/dt  =>  [Φ] = [e] × [t] = Volt × second.\n\n4. STEP-BY-STEP SOLUTION:\n1. From Faraday's law, induced electromotive force e = -dΦ/dt.\n2. Rearranging gives dΦ = e dt.\n3. Therefore, 1 Weber (Wb) = 1 Volt · second (V·s).\n4. In base units, 1 Wb = 1 kg·m²·s⁻²·A⁻¹.\n\n5. FINAL ANSWER:\nOption B: 1 V·s\n\n6. QUICK TIP:\nNEET Memory Aid: 1 Wb = 1 V·s = 1 T·m².",
