      "formula": "Faraday's law of electromagnetic induction: e = -dΦ/dt  =>  [Φ] = [e] × [t] = Volt × second.",
      "stepByStep": "1. From Faraday's law, induced electromotive force e = -dΦ/dt.\n2. Rearranging gives dΦ = e dt.\n3. Therefore, 1 Weber (Wb) = 1 Volt · second (V·s).\n4. In base units, 1 Wb = 1 kg·m²·s⁻²·A⁻¹.",
