    "explanation": "1. CONCEPT:\nDefinition and unit of electrical capacitance.\n\n2. GIVEN:\nCapacitance C of a conductor.\n\n3. FORMULA / PRINCIPLE:\nQ = C · V  =>  C = Q / V.\n\n4. STEP-BY-STEP SOLUTION:\n1. Capacitance is defined as the ratio of stored electric charge Q to potential difference V.\n2. Charge Q is measured in Coulombs (C).\n3. Potential difference V is measured in Volts (V).\n4. Hence, 1 Farad = 1 Coulomb / Volt (C/V).\n\n5. FINAL ANSWER:\nOption A: Coulomb per Volt (C/V)\n\n6. QUICK TIP:\nNEET High-Yield Tip: 1 Farad = 1 C/V = 1 A·s/V = 1 s/Ω.",
