      "stepByStep": "1. Capacitance is defined as the ratio of stored electric charge Q to potential difference V.\n2. Charge Q is measured in Coulombs (C).\n3. Potential difference V is measured in Volts (V).\n4. Hence, 1 Farad = 1 Coulomb / Volt (C/V).",
      "finalAnswer": "Option A: Coulomb per Volt (C/V)",
