    "correctIndex": 1,
    "explanation": "1. CONCEPT:\nIdentification of physical constants from their derived units.\n\n2. GIVEN:\nUnit: T·m/A.\n\n3. FORMULA / PRINCIPLE:\nB = μ₀ I / (2π r)  =>  μ₀ = 2π r B / I  =>  m · T / A = T·m/A.\n\n4. STEP-BY-STEP SOLUTION:\n1. From Biot-Savart law or Ampere's law, magnetic field around a long wire is B = μ₀ I / (2π r).\n2. Rearrange for μ₀: μ₀ = 2π r B / I.\n3. The units are: (meter × Tesla) / Ampere = T·m/A.\n4. This can also be written as N/A² or H/m.\n5. Therefore, quantity X is the permeability of free space μ₀.\n\n5. FINAL ANSWER:\nOption B: Permeability of free space μ₀\n\n6. QUICK TIP:\nNEET Memory Rule: μ₀ has units: T·m/A = N/A² = H/m. All three are identical!",
