    "explanation": "1. CONCEPT:\nDecomposition of electromagnetic units into mechanical power.\n\n2. GIVEN:\nUnit: Wb · A / s.\n\n3. FORMULA / PRINCIPLE:\n1 Wb = 1 V·s  =>  (Wb · A) / s = (V · s · A) / s = V · A = Watt (Power).\n\n4. STEP-BY-STEP SOLUTION:\n1. Express Weber in terms of Volts: 1 Wb = 1 V·s (from Faraday's law e = dΦ/dt).\n2. Substitute into the expression:\n   (Wb · A) / s = (V · s · A) / s = V · A.\n3. Electric power P = V · I, and Volt × Ampere = Watt (W) = Joule/second.\n4. Therefore, the quantity represents Power.\n\n5. FINAL ANSWER:\nOption B: Power\n\n6. QUICK TIP:\nNEET Shortcut: Wb/s is induced EMF in Volts! Volts × Amperes is electric power in Watts! Thus (Wb/s) × A = Power!",
